mapper.select:
SELECT * FROM (
    SELECT * FROM ANS_BREAKING_NEWS WHERE TITLE LIKE CONCAT('%', #{keyword}, '%') 
    UNION 
    SELECT * FROM ANS_MAIN_NEWS WHERE TITLE LIKE CONCAT('%', #{keyword}, '%')
) AS search_results 
LIMIT #{pageSize} OFFSET #{offset}

SELECT IDX, TITLE, SMR, PRESS, IMG_URL1, URL
FROM ANS_MAIN_NEWS 
WHERE idx=#{idx}

SELECT IDX, TITLE, SMR, PRESS, IMG_URL1, URL
FROM ANS_BREAKING_NEWS  
WHERE idx=#{idx}

SELECT COUNT(*) FROM ANS_FAV
WHERE ID = #{id}
AND (
    (#{type} = 'breaking' AND BREAKING_IDX = #{idx}) OR
    (#{type} = 'main' AND MAIN_IDX = #{idx})
)

SELECT idx, id, main_idx, breaking_idx, create_dt
FROM ANS_FAV
WHERE id = #{id}
ORDER BY create_dt DESC
LIMIT #{offset}, #{pageSize}

SELECT idx, title, smr, press
FROM ANS_MAIN_NEWS
WHERE idx = #{idx}

SELECT idx, title, smr, press
FROM ANS_BREAKING_NEWS
WHERE idx = #{idx}
